INSERT INTO P_HISTORY (
  	historyid
  	,categoryid
  	,productid
  	,usrno
  	,bfrpnm
  	,updnm
  	,bfrprice
  	,updprice
  	,bfrtitle
  	,updtitle
  	,bfrcont
  	,updtcont
  	,bfrqty
  	,updtqty
  	,gbn
  	,rdate
) VALUES (
	p_history_seq.NEXTVAL
	,#{oivo.categoryid}
	,#{oivo.productid}
	,#{ovo.usrno}
	,#{oivo.pnm}
	,null
	,#{oivo.price}
	,null
	,#{oivo.title}
	,null
	,#{oivo.cont}
	,null
	,#{oivo.pqty}
	,#{oivo.pqty} - #{oivo.qty}
	,'o'
	,sysdate
)

mapper.select:
SELECT PRODUCTID ,CATEGORYID ,CATEGORYNAME ,PNM ,title ,PRICE ,QTY ,IMGNM ,row_num ,rdate FROM ( SELECT a.PRODUCTID ,a.CATEGORYID ,CASE TO_CHAR(a.CATEGORYID) WHEN '1' THEN '과일류' WHEN '2' THEN '채소류' WHEN '3' THEN '육류' WHEN '4' THEN '어류' WHEN '5' THEN '밀키트' ELSE '기타' END AS CATEGORYNAME , a.PNM ,a.title , a.PRICE , a.QTY,
NVL(b.IMGNM, '') AS IMGNM , ROW_NUMBER() OVER(ORDER BY a.PRODUCTID DESC) AS row_num ,a.rdate FROM PRODUCTS a LEFT JOIN ( SELECT PRODUCTID , IMGNM FROM ( SELECT PRODUCTID , IMGNM , ROW_NUMBER() OVER(PARTITION BY PRODUCTID ORDER BY IMGNM ASC) as rn FROM p_Gallery ) WHERE rn = 1 ) b ON a.PRODUCTID = b.PRODUCTID
a.delyn = 'N'
AND PNM like '%'|| #{searchValue} ||'%'
AND title like '%'|| #{searchValue} ||'%'
) products_numrow_view WHERE row_num BETWEEN #{begin} AND #{end}

SELECT HISTORYID ,PRODUCTID ,USRNO ,USRNM ,qty ,pnm ,BFRPNM ,UPDNM ,BFRPRICE ,UPDPRICE ,BFRTITLE ,UPDTITLE ,BFRCONT ,UPDTCONT ,BFRQTY ,UPDTQTY ,gbn ,RDATE ,row_num FROM ( SELECT h.HISTORYID ,p.PRODUCTID ,u.USRNO ,u.USRNM ,p.qty ,p.pnm ,h.BFRPNM ,h.UPDNM ,h.BFRPRICE ,h.UPDPRICE ,h.BFRTITLE ,h.UPDTITLE ,h.BFRCONT ,h.UPDTCONT ,h.BFRQTY ,h.UPDTQTY ,h.GBN ,h.RDATE ,ROW_NUMBER() OVER(ORDER BY h.HISTORYID DESC) AS row_num FROM P_HISTORY h JOIN USERS u ON h.USRNO = u.USRNO JOIN PRODUCTS p ON p.PRODUCTID = h.PRODUCTID
1=1
AND h.gbn like '%'|| #{searchValue} ||'%'
AND u.USRNM like '%'|| #{searchValue} ||'%'
) p_history_view WHERE row_num BETWEEN #{begin} AND #{end}

mapper.update:
update products
	set
	pnm = #{updnm}
	,title = #{updtitle}
	,cont = #{updtcont}
	,price = #{updprice}
	,qty = #{updtqty}
	,rdate = sysdate
where productid = #{productid}

update P_HISTORY 
	set 
	updnm = #{updnm}
	,updtitle = #{updtitle}
	,updtcont = #{updtcont}
	,updtqty = #{updtqty}
	,updprice = #{updprice}
	,usrno = #{usrno}
	,rdate = sysdate
 where historyid = #{historyid}
